package com.vandorlabs.neoforge.storage;
import com.google.gson.*;
import com.vandorlabs.neoforge.ModernFinishCatalog;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Immutable authored Storage descriptors. No worlds, stacks or atlas objects are retained. */
public final class NativeStorageAssets {
 public record Texture(String id,int width,int height,int canvas,float u,float v){}
 public record Artwork(int choice,Texture front,Texture side,Texture top) {public Texture face(int local){return local==2?front:local<=1?top:side;}}
 private record Data(List<Texture> textures,Map<Integer,Artwork> sets,Map<Integer,ModernFinishCatalog.Entry> presentation){}
 private static final class Holder {static final Data DATA=load();}
 private NativeStorageAssets(){}
 private static Data load(){try(var stream=NativeStorageAssets.class.getResourceAsStream("/assets/vandorlabs/data/storage_artwork.json")){if(stream==null)throw new IllegalStateException("Missing Storage artwork");byte[] bytes=stream.readNBytes(65537);if(bytes.length>65536)throw new IllegalStateException("Storage artwork descriptor bound");var root=JsonParser.parseString(new String(bytes,StandardCharsets.UTF_8)).getAsJsonObject();if(root.get("schema").getAsInt()!=1)throw new IllegalStateException("Storage artwork schema");var textures=new TreeMap<String,Texture>();for(var value:root.getAsJsonArray("textures")){var row=value.getAsJsonObject();String id=row.get("id").getAsString();int w=row.get("width").getAsInt(),h=row.get("height").getAsInt(),canvas=row.get("canvas").getAsInt();float u=row.get("u").getAsFloat(),v=row.get("v").getAsFloat();if(!id.matches("vandorlabs:blocks/storage/[a-z0-9_]+")||w<1||h<1||canvas<Math.max(w,h)||canvas>256||(canvas&(canvas-1))!=0||!Float.isFinite(u)||!Float.isFinite(v)||Math.abs(u-w/(float)canvas)>1e-6||Math.abs(v-h/(float)canvas)>1e-6||textures.put(id,new Texture(id,w,h,canvas,u,v))!=null)throw new IllegalStateException("Invalid Storage texture");}var sets=new HashMap<Integer,Artwork>();var views=new HashMap<Integer,ModernFinishCatalog.Entry>();for(var value:root.getAsJsonArray("sets")){var row=value.getAsJsonObject();int choice=row.get("choice").getAsInt();var front=textures.get(row.get("front").getAsString());var side=textures.get(row.get("side").getAsString());var top=textures.get(row.get("top").getAsString());if(choice<0||choice>=ModernFinishCatalog.ENTRIES.size()||front==null||side==null||top==null||sets.put(choice,new Artwork(choice,front,side,top))!=null)throw new IllegalStateException("Invalid Storage set");var old=ModernFinishCatalog.option(choice);views.put(choice,new ModernFinishCatalog.Entry(old.id(),old.label(),old.category(),old.visible(),old.general(),old.canonical(),front.id(),front.u(),front.v(),old.displaySelectable(),old.frame(),old.playback(),old.door()));}if(textures.size()!=42||sets.size()!=14)throw new IllegalStateException("Incomplete Storage artwork");return new Data(List.copyOf(textures.values()),Map.copyOf(sets),Map.copyOf(views));}catch(java.io.IOException failure){throw new IllegalStateException("Cannot read Storage artwork",failure);}}
 public static List<Texture> textures(){return Holder.DATA.textures;}public static Map<Integer,Artwork> sets(){return Holder.DATA.sets;}
 public static ModernFinishCatalog.Entry presentation(int choice){var known=Holder.DATA.presentation.get(choice);return known==null?ModernFinishCatalog.option(choice):known;}
}
